INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('messenger-statt-sms-oesterreich-rtr-telekom-monitor-2026','Messenger statt SMS: Österreicher tippen 25,5 Milliarden Chats','Rund 25,5 Milliarden Chatnachrichten, aber nur 192 Millionen SMS: Die neuen RTR-Berichte zeigen, wie stark Messenger-Apps SMS und klassische Handytelefonate verdrängen.','Messenger statt SMS: Dieser Trend setzt sich in Österreich ungebremst fort. Laut den aktuellen Marktberichten der Regulierungsbehörde RTR wurden im ersten Quartal 2026 rund 25,5 Milliarden Chatnachrichten über Messengerdienste verschickt – etwa drei Prozent mehr als im Vergleichszeitraum des Vorjahres. Die klassische SMS und das herkömmliche Handytelefonat verlieren dagegen weiter an Bedeutung.

Die Zahlen stammen aus dem RTR Internet Monitor und dem RTR Telekom Monitor, die die Rundfunk und Telekom Regulierungs-GmbH am 21. Oktober 2026 für das erste Quartal veröffentlicht hat. Die beiden Berichte erscheinen regelmäßig und bilden den heimischen Telekommunikationsmarkt ab.

## Messenger statt SMS: Die wichtigsten Zahlen

Die Verschiebung hin zu internetbasierten Diensten zeigt sich sowohl beim Schreiben als auch beim Telefonieren:

- **Chatnachrichten:** rund 25,5 Milliarden im ersten Quartal 2026, ein Plus von etwa 3 Prozent gegenüber dem ersten Quartal 2025.
- **SMS:** 192 Millionen verschickte Kurznachrichten, das sind um mehr als 10 Prozent weniger als ein Jahr davor.
- **Messenger-Telefonie:** 8,9 Milliarden Gesprächsminuten über Messengerdienste, ein Zuwachs von rund 7 Prozent.
- **Klassische Mobiltelefonie:** 5,8 Milliarden Gesprächsminuten über das Mobilfunknetz, ein Rückgang von etwa 3 Prozent.

Auf jede herkömmlich verschickte SMS kommen damit rechnerisch mehr als hundert Chatnachrichten. Auch beim Telefonieren liegt der Messenger inzwischen klar vorne: Über Apps wird deutlich mehr gesprochen als über die klassische Mobilfunk-Sprachverbindung.

## Warum die SMS trotzdem nicht verschwindet

Ganz abgeschrieben ist die Kurznachricht laut RTR aber nicht. Vor allem im Verkehr zwischen Unternehmen und Kundinnen und Kunden bleibt sie wichtig. Typische Beispiele sind Bestätigungscodes beim Onlinebanking, Terminerinnerungen oder Zustellbenachrichtigungen. Für solche Anwendungen ist die SMS nach wie vor ein verbreiteter Kanal, weil sie ohne zusätzliche App und unabhängig von einer Internetverbindung funktioniert.

Im privaten Austausch dominieren dagegen Messenger-Apps, die über mobile Daten oder WLAN laufen. Sie ermöglichen neben Text auch Sprachnachrichten, Bilder, Videos und Gruppenchats – und verursachen bei den meisten Tarifen keine zusätzlichen Kosten pro Nachricht.

## Mobilfunkmarkt: HoT erstmals zweistellig

Der Telekom Monitor liefert auch die aktuellen Marktanteile im österreichischen Mobilfunk. Die Reihenfolge an der Spitze bleibt unverändert:

1. A1 Telekom Austria mit 36,2 Prozent
2. Magenta mit 24,8 Prozent
3. Hutchison (Drei) mit 20 Prozent
4. Ventocom mit der Marke HoT mit 10 Prozent
5. Mass Response mit der Marke spusu mit 5,5 Prozent

Bemerkenswert ist der Wert von HoT: Der Diskontanbieter erreicht laut RTR damit erstmals einen zweistelligen Marktanteil. Die drei Netzbetreiber A1, Magenta und Drei kommen gemeinsam auf rund 81 Prozent.

## Was die RTR-Berichte enthalten

Der RTR Internet Monitor befasst sich mit Breitband im Fest- und Mobilnetz, mit Ergebnissen des RTR-Netztests, mit Auswertungen der Zentralen Informationsstelle für Breitbandversorgung sowie mit Daten zu internetbasierten Kommunikationsdiensten. Der Telekom Monitor deckt Mobilfunk, Breitband, Festnetz, Mietleitungen und Glasfaser ab.

Die Daten hinter den Grafiken stellt die RTR im Open-Data-Bereich ihrer Website zur Verfügung. Die Behörde steht zu hundert Prozent im Eigentum des Bundes und unterstützt unter anderem die Telekom-Control-Kommission und die KommAustria.

Für Konsumentinnen und Konsumenten bedeutet die Entwicklung vor allem eines: Bei der Tarifwahl rückt das Datenvolumen immer stärker in den Vordergrund, während Freiminuten und SMS-Pakete an Gewicht verlieren.','wirtschaft','Unternehmen',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/messenger-statt-sms-oesterreich-rtr-telekom-monitor-2026.webp','RTR – Rundfunk und Telekom Regulierungs-GmbH (APA-OTS)','https://www.ots.at/presseaussendung/OTS_20261021_OTS0006/messengerdienste-draengen-klassische-mobilfunktelefonie-und-sms-versand-zusehends-ins-abseits','published','2026-10-22T04:55:00.000Z','2026-10-22T04:45:45.690Z','Messenger statt SMS: 25,5 Mrd. Chats in Österreich','Messenger statt SMS: Laut RTR wurden im 1. Quartal 2026 rund 25,5 Milliarden Chats verschickt. Alle Zahlen und Marktanteile im Überblick.','Messenger statt SMS','["Messenger statt SMS","RTR Telekom Monitor","RTR Internet Monitor","SMS Rückgang Österreich","Chatnachrichten Österreich 2026","Mobilfunk Marktanteile Österreich","HoT Marktanteil","Messenger Telefonie Minuten"]','Messenger statt SMS: Fahrgäste in einer Wiener Straßenbahn tippen Nachrichten am Smartphone','Commuters on a Vienna tram in autumn morning light seen from behind and the side, people looking down at their smartphones typing messages, blurred Viennese facades outside the window, photorealistic, no text, no logos, no readable signs','[{"q":"Wie viele Chatnachrichten wurden in Österreich im ersten Quartal 2026 verschickt?","a":"Laut RTR rund 25,5 Milliarden, etwa drei Prozent mehr als im ersten Quartal 2025."},{"q":"Wie stark ist die Zahl der SMS gesunken?","a":"Im ersten Quartal 2026 wurden 192 Millionen SMS verschickt, um mehr als zehn Prozent weniger als ein Jahr zuvor."},{"q":"Welcher Mobilfunker hat den größten Marktanteil?","a":"A1 Telekom Austria mit 36,2 Prozent, vor Magenta mit 24,8 und Drei mit 20 Prozent."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
